  q(TECH,'An electronic prescription for a controlled substance must use which security step?','Two-factor authentication',['A handwritten signature','A fax confirmation','A pharmacy phone call'],'A','DEA rules for e-prescribing controlled substances require identity proofing and two-factor authentication.',MOINI)
